import json, re
from pathlib import Path
import xml.etree.ElementTree as ET
s=json.loads(Path('source.json').read_text())[0]
a=json.loads(Path('answer.json').read_text())[0]
for label,xml in [('SOURCE INTEGRALE RELUE',s['source_xml']),('PROPOSITION INTEGRALE A RELIRE',a['proposed_xml'])]:
 print('\\n'+label)
 root=ET.fromstring('<root>'+xml+'</root>')
 for node in root:
  if node.tag=='table':
   for row in node.findall('./tbody/tr'):
    print(' | '.join(re.sub(r'\\s+',' ',''.join(cell.itertext())).strip() for cell in row))
  else:
   txt=re.sub(r'\\s+',' ',''.join(node.itertext())).strip()
   if txt: print(txt)
PY"

